def solve(case):
    segments = case['segments']
    budget = case['budget']

    # Validate presence of required fields
    for seg in segments:
        if not all(k in seg for k in ('name', 'importance', 'minimum', 'capacity')):
            raise ValueError("Segment missing required field")

    sum_min = sum(seg['minimum'] for seg in segments)
    sum_cap = sum(seg['capacity'] for seg in segments)

    if budget < sum_min or budget > sum_cap:
        raise ValueError("Budget out of feasible range")

    allocations = [seg['minimum'] for seg in segments]
    remaining = budget - sum_min

    while remaining > 0:
        # Find index of best segment: max importance/(current+1), tie-break by original index
        best_idx = -1
        best_score = None
        for i, seg in enumerate(segments):
            if allocations[i] < seg['capacity']:
                score = Fraction(seg['importance'], allocations[i] + 1)
                if best_score is None or score > best_score or (score == best_score and i < best_idx):
                    best_score = score
                    best_idx = i
        if best_idx == -1:
            # Should not happen because budget <= sum_cap, but safety
            raise ValueError("No segment can accept more tokens")
        allocations[best_idx] += 1
        remaining -= 1

    total = sum(allocations)
    by_name = {segments[i]['name']: allocations[i] for i in range(len(segments))}
    return {
        'allocations': allocations,
        'by_name': by_name,
        'total': total
    }
